const Confetti = defineUi<ConfettiProps>("Confetti", ["class", "active", "burstKey", "apiRef", "origin", "count", "spread", "angle", "velocity", "gravity", "drift", "duration", "colors", "shapes", "scalar", "seed", "onDone"], (_props, {
